import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const b=JSON.parse('{"title":"DataV · 大屏组件、2.5D 地图与行政区","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/datav.md","filePath":"modules/catalog/datav.md","lastUpdated":1795232822000}'),r={name:"modules/catalog/datav.md"};function c(n,t,l,h,i,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="datav-·-大屏组件、2-5d-地图与行政区" tabindex="-1">DataV · 大屏组件、2.5D 地图与行政区 <a class="header-anchor" href="#datav-·-大屏组件、2-5d-地图与行政区" aria-label="Permalink to &quot;DataV · 大屏组件、2.5D 地图与行政区&quot;">​</a></h1><p>集中说明 datav 方向的大屏组件（边框 / 装饰 / 图表 / 飞线）、2.5D 地图、行政区数据与 GeoJSON 工具。</p><h2 id="上游来源" tabindex="-1">上游来源 <a class="header-anchor" href="#上游来源" aria-label="Permalink to &quot;上游来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>上游</th><th>用到的部分</th></tr></thead><tbody><tr><td><a href="https://github.com/vaemusic/datav-vue3" target="_blank" rel="noreferrer">vaemusic/datav-vue3</a>（MIT，npm 包 <code>@kjgl77/datav-vue3</code>）</td><td>边框、装饰、图表、飞线等组件的实现，内化后保留原有 props 与渲染行为</td></tr><tr><td><a href="https://github.com/fengtianxi001/MF-2.5DMap" target="_blank" rel="noreferrer">fengtianxi001/MF-2.5DMap</a></td><td><code>DvMap25D</code> 与地图贴图</td></tr></tbody></table><p>飞线图示例的河南底图、城市点位图与相对坐标取自 datav-vue3 的演示；换省份时按同一套比例改 <code>points</code> 即可。</p><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/comps-vue3-datav</code></td><td>Vue 3 数据可视化组件与地图工具</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>demo-vue3-datav</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3-datav/dist/index.html" target="_blank" rel="noreferrer">演示地址</a>（Playground 中 <code>Dv</code> 前缀条目）</td></tr></tbody></table><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td><code>installDatavComponents</code></td><td>全局组件注册</td></tr><tr><td><code>loadGeojson</code> / <code>clearGeojsonCache</code> / <code>resolveGeojsonUrl</code></td><td>GeoJSON 加载、缓存清理和地址解析</td></tr><tr><td><code>getFeatureCenter</code> / <code>getGeojsonBbox</code> / <code>findRegion</code></td><td>地图特征、包围盒与行政区查询</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td><code>DvMap25D</code> / <code>DvRegionSelect</code></td><td>2.5D 行政区地图、行政区选择</td></tr><tr><td><code>DvBorderBox1</code>–<code>DvBorderBox13</code></td><td>大屏边框容器</td></tr><tr><td><code>DvDecoration1</code>–<code>DvDecoration12</code></td><td>装饰元素</td></tr><tr><td><code>DvFlylineChart</code> / <code>DvFlylineChartEnhanced</code></td><td>点位飞线图、带航线 / 光晕 / 图标的增强飞线图</td></tr><tr><td><code>DvCapsuleChart</code> / <code>DvConicalColumnChart</code> / <code>DvActiveRingChart</code> / <code>DvWaterLevelPond</code> / <code>DvPercentPond</code></td><td>胶囊柱图、锥形柱图、主动环图、水位池、百分比池</td></tr><tr><td><code>DvScrollBoard</code> / <code>DvScrollRankingBoard</code> / <code>DvDigitalFlop</code> / <code>DvCharts</code> / <code>DvButton</code> / <code>DvLoading</code> / <code>DvFullScreenContainer</code></td><td>轮播表、轮播榜单、数字翻牌、通用图表、按钮、加载与全屏容器</td></tr></tbody></table><h2 id="飞线图配置" tabindex="-1">飞线图配置 <a class="header-anchor" href="#飞线图配置" aria-label="Permalink to &quot;飞线图配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>centerPoint</code></td><td>中心点相对坐标 <code>[x, y]</code>，取值 0~1</td></tr><tr><td><code>points</code></td><td>起点列表，元素为 <code>{ position: [x, y], text }</code></td></tr><tr><td><code>bgImgUrl</code></td><td>底图地址</td></tr><tr><td><code>centerPointImg</code> / <code>pointsImg</code></td><td>中心点 / 点位图片，形如 <code>{ url }</code></td></tr><tr><td><code>dev</code></td><td>点击舞台时在控制台输出相对坐标，用来标点位</td></tr></tbody></table><p><code>DvFlylineChartEnhanced</code> 用 <code>points[].name</code> 配合 <code>lines[]</code> 描述航线，<code>icon</code> / <code>text</code> / <code>k</code> 控制图标、文案与飞线弧度。组件本身不自撑高度，父容器需要给出明确宽高；舞台比例建议与底图一致，否则地图会被拉伸。</p><h2 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to &quot;接入方式&quot;">​</a></h2><p>对应 <code>demo-vue3-datav</code>。地理数据与组件均从包公开入口使用，后续在此补充数据源配置与自部署方式。</p>',18)])])}const u=e(r,[["render",c]]);export{b as __pageData,u as default};
